function validate([n, dislikes]) {
  if (!Number.isInteger(n) || n < 1 || n > 2000) return 'n is between 1 and 2000.';
  if (!Array.isArray(dislikes) || dislikes.length > 10000) return 'dislikes has at most 10^4 pairs.';
  const seen = new Set();
  for (const pair of dislikes) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each dislike is a pair [a, b].';
    const [a, b] = pair;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || a >= b || b > n) return 'Each pair needs 1 <= a < b <= n.';
    const key = a * 4096 + b;
    if (seen.has(key)) return 'The same pair cannot appear twice.';
    seen.add(key);
  }
  return null;
}

