function possibleBipartition(n, dislikes) {
  if (n <= 16) {
    // Try every way to split the people into two groups.
    for (let mask = 0; mask < (1 << n); mask++) {
      const side = (p) => (mask >> (p - 1)) & 1;
      if (dislikes.every(([a, b]) => side(a) !== side(b))) return true;
    }
    return false;
  }
  // Larger inputs: everyone a person dislikes must share one group.
  const parent = Array.from({ length: n + 1 }, (_, i) => i);
  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  const enemies = Array.from({ length: n + 1 }, () => []);
  for (const [a, b] of dislikes) { enemies[a].push(b); enemies[b].push(a); }
  for (let p = 1; p <= n; p++) {
    for (const q of enemies[p]) {
      if (find(p) === find(q)) return false;
      parent[find(q)] = find(enemies[p][0]);
    }
  }
  return true;
}

