function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 8);
  const maxPairs = n * (n - 1) / 2;
  const want = size === 'large' ? Math.min(1999, Math.floor(n * (0.5 + rand()))) : Math.floor(rand() * (Math.min(maxPairs, 10) + 1));
  const side = Array.from({ length: n + 1 }, () => rand() < 0.5);
  const mode = rand();
  const seen = new Set();
  const dislikes = [];
  let attempts = 0;
  while (dislikes.length < want && attempts < 50 * (want + 1)) {
    attempts++;
    let a = 1 + Math.floor(rand() * n);
    let b = 1 + Math.floor(rand() * n);
    if (a === b) continue;
    if (a > b) [a, b] = [b, a];
    // Most inputs keep every pair across the two hidden sides, so the answer is often true.
    if (mode < 0.6 && side[a] === side[b]) continue;
    const key = a * 4096 + b;
    if (seen.has(key)) continue;
    seen.add(key);
    dislikes.push([a, b]);
  }
  if (mode < 0.6 && rand() < 0.35 && dislikes.length > 0) {
    // Add one pair inside a side, which may create an odd cycle.
    for (let t = 0; t < 50; t++) {
      let a = 1 + Math.floor(rand() * n);
      let b = 1 + Math.floor(rand() * n);
      if (a === b || side[a] !== side[b]) continue;
      if (a > b) [a, b] = [b, a];
      if (seen.has(a * 4096 + b)) continue;
      dislikes.splice(Math.floor(rand() * (dislikes.length + 1)), 0, [a, b]);
      break;
    }
  }
  return [n, dislikes];
}
